query NewIssueContext($owner: String!, $repo: String!, $status: String!, $window: Int!, $link0Owner: String!, $link0Repo: String!, $link0Number: Int!) {
  repository(owner: $owner, name: $repo) {
    id
    labels(first: 100, orderBy: {field: NAME, direction: ASC}) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes { id name }
    }
    milestones(first: 100, states: OPEN, orderBy: {field: NUMBER, direction: ASC}) {
      totalCount
      pageInfo { hasNextPage endCursor }
      nodes { id title dueOn }
    }
    issues(last: $window, states: OPEN, orderBy: {field: CREATED_AT, direction: ASC}) {
      nodes {
        id
        number
        title
        body
        viewerDidAuthor
        labels(first: 50) { nodes { name } }
        milestone { title dueOn }
        projectItems(first: 20) {
          nodes {
            id
            isArchived
            project { id }
            fieldValueByName(name: $status) { ... on ProjectV2ItemFieldSingleSelectValue { name } }
          }
        }
      }
    }
  }
  link0: repository(owner: $link0Owner, name: $link0Repo) {
    nameWithOwner
    issueOrPullRequest(number: $link0Number) { __typename ... on Issue { id title state blocking(first: 50) { nodes { id } } blockedBy(first: 50) { nodes { id } } } }
  }
}
